function applyApprovedRecipeConsumption(data,order,referenceId,createdAt){const movements=[];for(const line of Array.isArray(order?.cart)?order.cart:[]){const productId=line.productId||line.id||line.menuId,recipe=(data.recipes||[]).find(x=>String(x.productId)===String(productId)&&['APPROVED','ACTIVE','POSTED'].includes(String(x.status||'').toUpperCase())&&Array.isArray(x.ingredientLines)&&x.ingredientLines.length);if(!recipe)continue;const orderQty=Number(line.quantity)||0;for(const ingredient of recipe.ingredientLines){const item=data.inventoryItems.find(x=>String(x.id)===String(ingredient.inventoryItemId));const perUnit=Number(ingredient.quantity??ingredient.amount??ingredient.quantityPerProduct);if(!item||!Number.isFinite(perUnit)||perUnit<=0||orderQty<=0)continue;const delta=perUnit*orderQty;item.currentStock=Math.max(0,Number(item.currentStock||0)-delta);item.updatedAt=createdAt;const movement={id:adminId('mov'),type:'SALE_CONSUMPTION',inventoryItemId:item.id,quantity:-delta,unit:item.baseUnit||item.unit,referenceId,orderId:order.id,createdAt,notes:'Verbrauch durch Verkauf '+(order.displayCode||order.id)};data.stockMovements.push(movement);movements.push(movement)}}if(movements.length)data.auditEvents.push({id:adminId('audit'),type:'SALE_INVENTORY_CONSUMED',orderId:order.id,createdAt,details:{movementCount:movements.length}});return movements;}
function reply(res,status,data){const body=JSON.stringify(data),headers={'Content-Type':'application/json; charset=utf-8','Content-Length':Buffer.byteLength(body),'Connection':'close','Cache-Control':'no-store','Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'GET,POST,OPTIONS','Access-Control-Allow-Headers':'Content-Type'};res.once('finish',()=>console.info('[NARA][RESPONSE_FINISH]',{status,headersSent:res.headersSent,writableEnded:res.writableEnded,finished:res.finished}));res.once('close',()=>console.info('[NARA][RESPONSE_CLOSE]',{status,headersSent:res.headersSent,writableEnded:res.writableEnded,finished:res.finished}));res.writeHead(status,headers);res.end(body);}
