  const response=await fetch('https://generativelanguage.googleapis.com/v1beta/interactions',{method:'POST',headers:{'Content-Type':'application/json','x-goog-api-key':geminiKey},body:JSON.stringify({model:process.env.GEMINI_MODEL||'gemini-3.8-flash',input:instruction})});
